 JSONObject functionsJson(){try{return new JSONObject(app.prefs.getString("userFunctions","{\"Hypot\":{\"params\":\"x,y\",\"body\":\"Sqrt(x^2+y^2)\",\"description\":\"计算直角三角形的斜边长度。\"}}"));}catch(Exception e){return new JSONObject();}}
 void functions(){ToolPage p=page("函数 FUNC");p.embedded(400,1820);
  p.listRow("1","添加或编辑函数","创建你自己的函数，例如：f(x) = x² + x/2。","info",this::manageFunctions,()->app.toast("点按新建函数；长按已有函数可以编辑"));p.section("我的数学函数");p.divider();
  JSONObject all=functionsJson();Iterator<String> it=all.keys();int i=3;while(it.hasNext()){String name=it.next();JSONObject f=all.optJSONObject(name);if(f==null)continue;String[] params=f.optString("params").split(",");TextView row=p.listRow(""+i++,name+"("+f.optString("params")+")",f.optString("description",f.optString("body")),"info",()->insert(()->app.formula.call(name,params.length)),()->editFunction(name));((android.view.View)row.getParent().getParent()).setOnLongClickListener(v->{editFunction(name);return true;});}
  show(p);
 }

 void manageFunctions(){ToolPage p=page("自定义函数");p.action("more","函数操作",()->ReferenceDialogs.choose(app,"自定义函数",new String[]{"新建函数"},i->editFunction("")));JSONObject all=functionsJson();if(!app.prefs.contains("userFunctions")&&all.length()==0){try{all.put("Hypot",new JSONObject().put("params","x,y").put("body","Sqrt(x^2+y^2)").put("description","计算直角三角形的斜边长度。"));}catch(Exception ignored){}}
  Iterator<String> it=all.keys();while(it.hasNext()){String name=it.next();JSONObject f=all.optJSONObject(name);if(f==null)continue;LinearLayout block=new LinearLayout(app);block.setOrientation(1);block.setPadding(p.dp(8),p.dp(14),p.dp(8),p.dp(8));TextView signature=ToolPage.text(app,name+"("+f.optString("params").replace(",",", ")+")",21);signature.setTypeface(UiFonts.MONO);block.addView(signature);TextView definition=ToolPage.text(app,f.optString("body"),18);definition.setTypeface(UiFonts.MONO);definition.setPadding(0,p.dp(10),0,p.dp(8));block.addView(definition);TextView description=ToolPage.text(app,f.optString("description"),18);block.addView(description);LinearLayout actions=new LinearLayout(app);actions.setGravity(android.view.Gravity.RIGHT);actions.addView(ToolPage.icon(app,"trash","删除函数 "+name,()->ReferenceDialogs.builder(app).setTitle("删除 "+name+"？").setNegativeButton("取消",null).setPositiveButton("删除",(d,w)->{JSONObject saved=functionsJson();saved.remove(name);app.prefs.edit().putString("userFunctions",saved.toString()).apply();home();manageFunctions();}).show(),.6f),new LinearLayout.LayoutParams(p.dp(68),p.dp(54)));actions.addView(ToolPage.icon(app,"historyEdit","编辑函数 "+name,()->editFunction(name),.65f),new LinearLayout.LayoutParams(p.dp(68),p.dp(54)));block.addView(actions);p.body.addView(block);p.divider();}
  LinearLayout footer=new LinearLayout(app);footer.setPadding(p.dp(16),0,p.dp(16),0);p.button(footer,"新建函数",()->editFunction("")).setBackground(ToolPage.rounded(app,ToolPage.ACCENT,4));p.addView(footer,new LinearLayout.LayoutParams(-1,p.dp(60)));show(p);
 }
 void editFunction(String name){editFunction(name,"");}
 void editFunction(String name,String seed){JSONObject found=functionsJson().optJSONObject(name);if(found==null&&name.equals("Hypot"))try{found=new JSONObject().put("params","x,y").put("body","Sqrt(x^2+y^2)");}catch(Exception ignored){}final JSONObject f=found;ToolPage p=page(name.isEmpty()?"新建函数":"编辑函数");p.inset(16);
  EditText n=p.field(p.body,"★ 名称","数学函数名称",name,false),params=p.field(p.body,"★ 参数","x,y,z",f==null?"":f.optString("params"),false);p.note("参数以空格或逗号(,)分隔").setPadding(0,0,0,0);
  EditText body=p.field(p.body,"★ 函数定义","Sqrt(x^2+y^2+z^2)",f==null?seed:f.optString("body"),true);body.setMinLines(2);body.getLayoutParams().height=p.dp(60);body.setBackgroundTintList(null);body.setBackgroundColor(0xff101010);p.note("您可以从计算器显示或编程编辑器复制表达式").setPadding(0,0,0,0);CheckBox trig=new CheckBox(app);trig.setText("三角函数");trig.setTextColor(ToolPage.TEXT);trig.setTextSize(android.util.TypedValue.COMPLEX_UNIT_DIP,16);trig.setButtonTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{ToolPage.ACCENT,ToolPage.MUTED}));trig.setChecked(f!=null&&f.optBoolean("trig"));p.body.addView(trig,new LinearLayout.LayoutParams(-1,p.dp(48)));EditText description=p.field(p.body,"描述","",f==null?"":f.optString("description"),true);description.setMinLines(2);
  p.button(p.body,"保存",()->{String fn=n.getText().toString().trim(),ps=params.getText().toString().trim().replaceAll("[\\s,]+",","),expr=body.getText().toString().trim();if(!fn.matches("[a-zA-Z][a-zA-Z0-9_]{0,31}")){n.setError("函数名格式不正确");return;}if(!fn.equals("Hypot")&&MathFunctions.ALL.stream().anyMatch(e->e.name.equalsIgnoreCase(fn))){n.setError("此名称是内置函数");return;}String[] names=ps.split(",");if(!ps.matches("[a-zA-Z][a-zA-Z0-9_]*(,[a-zA-Z][a-zA-Z0-9_]*)*")||new HashSet<>(Arrays.asList(names)).size()!=names.length){params.setError("参数须为不同的变量名");return;}if(expr.isEmpty()){body.setError("请填写表达式");return;}try{JSONObject all=functionsJson();all.remove(name);all.put(fn,new JSONObject().put("params",ps).put("body",expr).put("trig",trig.isChecked()).put("description",description.getText().toString()));app.prefs.edit().putString("userFunctions",all.toString()).apply();home();manageFunctions();}catch(Exception e){body.setError("保存失败");}}).setBackground(ToolPage.rounded(app,ToolPage.ACCENT,4));show(p);if(name.isEmpty())n.postDelayed(()->{n.requestFocus();((android.view.inputmethod.InputMethodManager)app.getSystemService(android.content.Context.INPUT_METHOD_SERVICE)).showSoftInput(n,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);},200);
 }
 String expandFunctions(String source){return expandFunctions(source,functionsJson(),app.angleMode);}
 static String expandFunctions(String source,JSONObject functions,int angleMode){String s=source;for(int pass=0;pass<20;pass++){boolean changed=false;Iterator<String> it=functions.keys();while(it.hasNext()){String name=it.next();JSONObject f=functions.optJSONObject(name);if(f==null)continue;Matcher m=Pattern.compile("\\b"+Pattern.quote(name)+"\\s*\\(").matcher(s);if(!m.find())continue;int begin=m.start(),open=m.end()-1,end=open+1,depth=1;ArrayList<String> args=new ArrayList<>();int start=end;for(;end<s.length();end++){char c=s.charAt(end);if(c=='('||c=='{'||c=='[')depth++;if(c==')'||c=='}'||c==']')depth--;if(depth==0){args.add(s.substring(start,end));break;}if(c==','&&depth==1){args.add(s.substring(start,end));start=end+1;}}if(depth!=0)throw new IllegalArgumentException("函数括号不完整");String[] params=f.optString("params").split(",");if(args.size()!=params.length)throw new IllegalArgumentException(name+" 需要 "+params.length+" 个参数");String body=f.optString("body");if(f.optBoolean("trig"))body=Formula.result(body).source(angleMode);for(int i=0;i<params.length;i++)body=body.replaceAll("\\b"+params[i]+"\\b",Matcher.quoteReplacement("scUserArg"+i));for(int i=0;i<params.length;i++)body=body.replace("scUserArg"+i,"("+args.get(i)+")");s=s.substring(0,begin)+"("+body+")"+s.substring(end+1);if(s.length()>100000)throw new IllegalArgumentException("函数展开过长");changed=true;}if(!changed)return s;}throw new IllegalArgumentException("函数循环调用或嵌套超过 20 层");}
 void matrices(){named(false);}void vectors(){named(true);}
 void named(boolean vector){named(vector,0);}
 void named(boolean vector,int tab){app.view.mode=vector?"VECTOR":"MATRIX";ToolPage p=page(vector?"向量 VECTOR":"矩阵 MATRIX");p.embedded(400,1820);p.tabs(new String[]{"NAMES","EDIT","MATH"},tab,i->{home();named(vector,i);});
  String prefix=vector?"Vct":"Mat";int i=1;
  if(tab<2)for(String suffix:new String[]{"A","B","C","D","Ans"}){String name=prefix+suffix;String[][] grid=loadGrid("grid:"+name,vector?1:3,vector?2:3,"0");String dimension=vector?"R"+grid[0].length:grid.length+" × "+grid[0].length;Runnable edit=()->{if(name.endsWith("Ans")){app.toast("答案由计算自动保存");return;}if(app.prefs.contains("grid:"+name))openGrid("grid:"+name,name,vector?"vector":"matrix",grid,null);else createNamed(name,vector);};p.listRow(""+i++,name,dimension,name.endsWith("Ans")?"":"historyEdit",()->{if(tab==1)edit.run();else insert(()->{if(!app.variables.containsKey(name)&&!name.endsWith("Ans")){StringBuilder value=new StringBuilder("{");for(int r=0;r<grid.length;r++){if(r>0)value.append(",");if(!vector)value.append("{");value.append(String.join(",",grid[r]));if(!vector)value.append("}");}app.variables.put(name,value.append("}").toString());}app.formula.symbol(name);});},edit);}
  else {String[] names=vector?new String[]{"Dot","Cross","Norm","Normalize"}:new String[]{"Det","Inverse","Transpose","MatrixRank","RowReduce","Eigenvalues","Eigenvectors","Tr","IdentityMatrix"};for(String name:names){MathFunctions.Entry entry=MathFunctions.ALL.stream().filter(e->e.name.equals(name)).findFirst().orElse(null);if(entry!=null)p.listRow(""+i++,name+"("+String.join(", ",entry.parameters)+")",entry.label,"info",()->insert(()->app.formula.call(entry.name,entry.parameters.length)),()->app.toast(entry.signature()));}}
  show(p);
 }

 void selectNamed(boolean vector){String pre=vector?"Vct":"Mat";String[] names={pre+"A",pre+"B",pre+"C",pre+"D"};ReferenceDialogs.choose(app,"编辑"+(vector?"向量":"矩阵"),names,i->{String key="grid:"+names[i];if(app.prefs.contains(key))openGrid(key,names[i],vector?"vector":"matrix",loadGrid(key,1,vector?3:3,"0"),null);else createNamed(names[i],vector);});}
 void createNamed(String name,boolean vector){if(vector){ReferenceDialogs.choose(app,"向量维数",new String[]{"2 维","3 维"},i->openGrid("grid:"+name,name,"vector",loadGrid("grid:"+name,1,i+2,"0"),null));return;}MatrixSizeDialog.show(app,(rows,cols)->openGrid("grid:"+name,name,"matrix",newGrid(rows,cols,"0"),null));}
 String[][] newGrid(int rows,int cols,String fallback){String[][] grid=new String[rows][cols];for(String[] row:grid)Arrays.fill(row,fallback);return grid;}

 String[][] loadGrid(String key,int rows,int cols,String fallback){try{JSONArray a=new JSONArray(app.prefs.getString(key,"[]"));if(a.length()>0){String[][] grid=new String[a.length()][];for(int r=0;r<a.length();r++){JSONArray row=a.getJSONArray(r);grid[r]=new String[row.length()];for(int c=0;c<row.length();c++)grid[r][c]=row.optString(c);}return grid;}}catch(Exception ignored){}String[][] grid=new String[rows][cols];for(String[] row:grid)Arrays.fill(row,fallback);return grid;}
 void openGrid(String key,String title,String kind,String[][] cells,String[] headers){if(!app.view.gridActive)savedFormula=app.formula.save();gridKey=key;gridKind=kind;app.view.grid=cells;app.view.gridTitle=title;app.view.gridHeaders=headers==null?new String[cells[0].length]:headers;if(headers==null)for(int c=0;c<app.view.gridHeaders.length;c++)app.view.gridHeaders[c]="C"+(c+1);app.view.gridRow=0;app.view.gridCol=0;app.view.gridActive=true;app.view.second=false;app.view.mode=kind.equals("stats")?"STAT":kind.toUpperCase(Locale.ROOT);app.formula.load(cells[0][0]);app.formula.root.defaultValue=true;home();app.changed();}
 void saveGrid(){JSONArray all=new JSONArray();for(String[] row:app.view.grid)all.put(new JSONArray(Arrays.asList(row)));app.prefs.edit().putString(gridKey,all.toString()).apply();}
 void cell(int row,int col){app.view.gridRow=row;app.view.gridCol=col;app.formula.load(app.view.grid[row][col]);app.formula.root.defaultValue=true;app.changed();}
 void commit(Runnable next){if(gridKind.equals("table")){next.run();return;}if(app.formula.empty()){app.view.grid[app.view.gridRow][app.view.gridCol]=gridKind.equals("stats")?"":"0";saveGrid();next.run();return;}if(!app.formula.complete()){app.error("请填完整当前单元格");return;}int r=app.view.gridRow,c=app.view.gridCol;boolean frequency=c==app.view.gridHeaders.length-1;String source=app.vars(app.formula.source(app.angleMode));app.task(()->{String result=app.engine.evaluate(source,false);if(!app.engine.evaluate("NumericQ("+result+")",false).equals("True"))throw new IllegalArgumentException("单元格需要数值");if(gridKind.equals("stats")){double value=app.engine.value(result);if(frequency&&(value<=0||value!=Math.rint(value)))throw new IllegalArgumentException("频数须为正整数");}return result;},value->{app.view.grid[r][c]=value;saveGrid();next.run();});}
 boolean handle(String action){if(modes.handle(action))return true;if(!app.view.gridActive)return false;if(action.equals("menu")||action.equals("mode")){commit(()->{finishGrid();app.press(action);});return true;}if(action.startsWith("gridcell:")){String[] parts=action.split(":");int r=Integer.parseInt(parts[1]),c=Integer.parseInt(parts[2]);commit(()->cell(r,c));return true;}if(action.equals("evaluate")||action.equals("down")||action.equals("up")){int r=app.view.gridRow,c=app.view.gridCol;commit(()->{int target=r+(action.equals("up")?-1:1);if(target>=app.view.grid.length&&gridKind.equals("stats")){app.view.grid=Arrays.copyOf(app.view.grid,app.view.grid.length+1);String[] row=new String[app.view.gridHeaders.length];Arrays.fill(row,"");row[row.length-1]="1";app.view.grid[target]=row;saveGrid();}cell(Math.max(0,Math.min(app.view.grid.length-1,target)),c);});return true;}if(action.equals("left")||action.equals("right")){int r=app.view.gridRow,c=Math.max(0,Math.min(app.view.gridHeaders.length-1,app.view.gridCol+(action.equals("left")?-1:1)));commit(()->cell(r,c));return true;}if(action.equals("stats")||action.equals("matrix")||action.equals("vector")||action.equals("gridDone")||action.equals("statsShortcut")&&gridKind.equals("stats")||action.equals("vectorShortcut")&&gridKind.equals("vector")){commit(()->{if(gridKind.equals("stats")){app.formula.restore(savedFormula);app.view.gridActive=false;statistics();}else{finishGrid();if(action.equals("vectorShortcut"))vectors();}});return true;}if(gridKind.equals("table")&&!action.equals("shift")&&!action.equals("alpha")){finishGrid();return false;}return false;}
 void finishGrid(){if(app.view.gridActive&&(gridKind.equals("matrix")||gridKind.equals("vector"))){StringBuilder source=new StringBuilder("{");for(int r=0;r<app.view.grid.length;r++){if(r>0)source.append(',');if(!gridKind.equals("vector"))source.append('{');source.append(String.join(",",app.view.grid[r]));if(!gridKind.equals("vector"))source.append('}');}source.append('}');app.variables.put(app.view.gridTitle,source.toString());app.save();}app.view.gridActive=false;app.formula.restore(savedFormula);app.changed();app.calculator();}
 void statistics(){statistics(0);}
 void openStatisticsData(){int cols=regression.equals("one")?2:3;String key="stat:"+(cols==2?"one":"paired");String[][] data=loadGrid(key,5,cols,"");for(String[] r:data)if(r[cols-1].isEmpty())r[cols-1]="1";openGrid(key,"DATA","stats",data,cols==2?new String[]{"X","Freq"}:new String[]{"X","Y","Freq"});}
 void statistics(int tab){app.view.mode="STAT";ToolPage p=page("统计 STAT");p.embedded(580,2020);p.tabs(new String[]{"DATA","总和","变量","最小最大值","分布"},tab,i->{home();statistics(i);});
  if(tab==0){p.listRow("1","数据","使用统计编辑器输入数据","info",this::openStatisticsData,()->app.toast("使用数字键输入，方向键切换单元格"));p.listRow("2",regression.equals("one")?"1-变量计算":"回归计算","根据输入数据显示统计值","info",()->statResult(regression.equals("one")?1:3),()->app.toast("数值按已保存的数据及频数计算"));p.section("统计计算类型");p.divider();
   String[] types={"1-VAR","A+BX","A+BX+CX^2","A+B·ln(X)","Ae^(BX)","A·X^B","A+B/X"},descriptions={"单变量数据 (x)","双变量数据 (x, y)，线性回归","双变量数据 (x, y)，二次回归","双变量数据 (x, y)，对数回归","双变量数据 (x, y)，指数回归（以 e 为底）","双变量数据 (x, y)，幂回归","双变量数据 (x, y)，逆数回归"},keys={"one","linear","quadratic","log","exponential","power","inverse"};
   for(int i=0;i<keys.length;i++){final int n=i;p.listRow(""+(i+4),types[i]+(keys[i].equals(regression)?"  ✅":""),descriptions[i],"info",()->{regression=keys[n];app.prefs.edit().putString("statRegression",regression).apply();home();statistics(0);},()->app.toast(descriptions[n]));}
  }else if(tab==4){int i=1;for(MathFunctions.Entry entry:MathFunctions.category("stat dist",""))p.listRow(""+i++,entry.name+"("+String.join(", ",entry.parameters)+")",entry.label,"info",()->insert(()->app.formula.call(entry.name,entry.parameters.length)),()->app.toast(entry.signature()));}
  else{TextView out=p.note("计算中…");String type=regression;String[][] rows=statRows();show(p);app.menuTools.work(out,()->{StatsData data=dataset(rows);LinkedHashMap<String,Double> values=new LinkedHashMap<>();if(tab==1){values.put("n",data.n);values.put("Σx",data.sx);values.put("Σx²",data.sxx);if(!type.equals("one")){values.put("Σy",data.sy);values.put("Σy²",data.syy);values.put("Σxy",data.sxy);}}if(tab==2){values.put("x̄",data.mean());values.put("σx²",data.populationVariance());values.put("σx",Math.sqrt(data.populationVariance()));if(data.n>1){values.put("sx²",data.sampleVariance());values.put("sx",Math.sqrt(data.sampleVariance()));}}if(tab==3){values.put("minX",data.min());values.put("maxX",data.max());}return statValues(values);},json->showStatValues(p,out,json,true));}
  if(tab==0)show(p);
 }

 String statValues(LinkedHashMap<String,Double> values){JSONArray result=new JSONArray();for(Map.Entry<String,Double> e:values.entrySet())result.put(new JSONArray().put(e.getKey()).put(Double.isFinite(e.getValue())?Double.toString(e.getValue()):"未定义"));return result.toString();}
 void showStatValues(ToolPage p,TextView output,String json,boolean numbered){
  p.body.removeView(output);try{JSONArray values=new JSONArray(json);for(int i=0;i<values.length();i++){JSONArray row=values.getJSONArray(i);String name=row.getString(0),value=row.getString(1);Runnable use=()->{if(value.equals("未定义")){app.toast("此项统计值未定义");return;}insert(()->app.formula.answer(value));};if(numbered)p.listRow(""+(i+1),name,value,"info",use,()->app.toast(name+" = "+value));else p.row(name,value,use);}}catch(JSONException e){app.error("统计结果读取失败");}
 }
 String[][] statRows(){return loadGrid("stat:"+(regression.equals("one")?"one":"paired"),1,regression.equals("one")?2:3,"");}
 StatsData dataset(String[][] data) throws Exception{ArrayList<Double> xs=new ArrayList<>(),ys=new ArrayList<>(),ws=new ArrayList<>();for(String[] row:data){if(row[0].isEmpty())continue;xs.add(app.engine.value(row[0]));ys.add(row.length==3?app.engine.value(row[1]):0);ws.add(app.engine.value(row[row.length-1]));}double[] x=new double[xs.size()],y=new double[x.length],w=new double[x.length];for(int i=0;i<x.length;i++){x[i]=xs.get(i);y[i]=ys.get(i);w[i]=ws.get(i);}return new StatsData(x,y,w);}
 void statResult(int kind){ToolPage p=page("STAT · "+new String[]{"总计","变量","MinMax","回归"}[kind]);p.embedded(580,2020);TextView out=p.note("计算中…");show(p);String type=regression;String[][] rows=statRows();app.menuTools.work(out,()->{StatsData data=dataset(rows);LinkedHashMap<String,Double> values=new LinkedHashMap<>();if(kind==0){values.put("n",data.n);values.put("Σx",data.sx);values.put("Σx²",data.sxx);if(!type.equals("one")){values.put("Σy",data.sy);values.put("Σy²",data.syy);values.put("Σxy",data.sxy);}}if(kind==1){values.put("x̄",data.mean());values.put("中位数",data.median());values.put("σx²",data.populationVariance());values.put("σx",Math.sqrt(data.populationVariance()));if(data.n>1){values.put("sx²",data.sampleVariance());values.put("sx",Math.sqrt(data.sampleVariance()));}}if(kind==2){values.put("Min",data.min());values.put("Max",data.max());}if(kind==3){double[] fit=data.regression(type);for(int i=0;i<fit.length-1;i++)values.put(""+(char)('a'+i),fit[i]);values.put("r",fit[fit.length-1]);}return statValues(values);},json->showStatValues(p,out,json,false));}
