 void more(){String source=app.formula.empty()?app.ans:app.vars(app.formula.calculationSource(app.angleMode,app.prefs.getBoolean("implicitPriority",true)));more(app.copyFormula(),source,false);}
 void moreResult(Formula input,String exact){more(input,exact,true);}
 private void more(Formula input,String source,boolean selectedResult){ToolPage p=page("MORE");p.inset(0);p.header.removeView(p.title);LinearLayout controls=new LinearLayout(app);p.header.addView(controls,new LinearLayout.LayoutParams(0,p.dp(36),1));
  newSegments(p,controls,new String[]{"DEG","RAD","GRA"},app.angleMode,i->{app.setAngle(i);home();if(selectedResult)more(input,source,true);else more();});newSegments(p,controls,new String[]{"DEC│0.5","FRAC│½"},app.decimal?0:1,i->{app.decimal=i==0;app.save();home();if(selectedResult)more(input,source,true);else more();});p.action("more","结果操作",app::copyMenu);
  moreBlock(p,"输入表达式",input.save(),input.source(app.angleMode),true);
  TextView pending=p.note("计算中…");show(p);boolean approximate=app.decimal;int digits=app.prefs.getInt("digits",11);String format=app.prefs.getString("numberFormat","normal");boolean scientific=app.prefs.getBoolean("scientificE",false);
  app.menuTools.work(pending,()->{String exact=app.engine.evaluate(source,false);LinkedHashMap<String,String> values=new LinkedHashMap<>();values.put("计算结果",approximate?ResultFormat.scientific(ResultFormat.format(app.engine.evaluate(exact,true,digits),format,digits),scientific):exact);
   if(app.engine.evaluate("IntegerQ("+exact+")",false).equals("True")){java.math.BigInteger integer=new java.math.BigInteger(exact);if(integer.signum()>0&&integer.compareTo(java.math.BigInteger.valueOf(3999))<=0)values.put("罗马数字",ResultFormat.roman(integer.intValue()));if(integer.signum()!=0&&integer.abs().bitLength()<=32){values.put("质因数分解",MathFunctions.factorDisplay(app.engine.evaluate("FactorInteger("+exact+")",false)));values.put("约数",app.engine.evaluate("Divisors(Abs("+exact+"))",false));}if(integer.bitLength()<=63){long n=integer.longValue();values.put("二进制 64 bits signed",BaseExpression.format(n,2));values.put("十六进制 64 bits signed",BaseExpression.format(n,16));values.put("八进制 64 bits signed",BaseExpression.format(n,8));}}
   try{String decimal=app.engine.evaluate(exact,true,digits);values.put("科学计数法",ResultFormat.scientific(ResultFormat.format(decimal,"scientific",digits),scientific));}catch(Exception ignored){}
   return new JSONObject(values).toString();},json->{p.body.removeView(pending);try{JSONObject values=new JSONObject(json);Iterator<String> keys=values.keys();while(keys.hasNext()){String key=keys.next();moreBlock(p,key,"",values.optString(key),!key.contains("bits"));}}catch(JSONException e){app.error("结果读取失败");}});
 }
 void newSegments(ToolPage p,LinearLayout parent,String[] labels,int selected,java.util.function.IntConsumer action){LinearLayout strip=new LinearLayout(app);strip.setPadding(p.dp(2),p.dp(2),p.dp(2),p.dp(2));strip.setBackground(ToolPage.rounded(app,0xff383d44,10));strip.setClipToOutline(true);for(int i=0;i<labels.length;i++){final int index=i;TextView t=ToolPage.text(app,labels[i],14);t.setGravity(android.view.Gravity.CENTER);t.setTextColor(i==selected?android.graphics.Color.BLACK:ToolPage.TEXT);if(i==selected)t.setBackground(ToolPage.rounded(app,ToolPage.ACCENT,9));strip.addView(t,new LinearLayout.LayoutParams(0,-1,1));t.setOnClickListener(v->action.accept(index));}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-1,1);lp.rightMargin=p.dp(8);parent.addView(strip,lp);}
 void moreBlock(ToolPage p,String title,String tree,String source,boolean actions){LinearLayout heading=new LinearLayout(app);heading.setGravity(android.view.Gravity.CENTER_VERTICAL);TextView text=ToolPage.text(app,title,18);text.setPadding(p.dp(8),0,0,0);heading.addView(text,new LinearLayout.LayoutParams(0,-1,1));Runnable use=()->insert(()->{app.formula.clear();if(!tree.isEmpty())app.formula.restore(tree);else app.formula.insertExpression(source);});if(actions){heading.addView(ToolPage.icon(app,"historyEdit","编辑"+title,use,.5f),new LinearLayout.LayoutParams(p.dp(46),-1));heading.addView(ToolPage.icon(app,"copy","复制"+title,()->{android.content.ClipboardManager clip=(android.content.ClipboardManager)app.getSystemService(android.content.Context.CLIPBOARD_SERVICE);clip.setPrimaryClip(android.content.ClipData.newPlainText(title,source));app.toast("已复制");},.5f),new LinearLayout.LayoutParams(p.dp(46),-1));}p.body.addView(heading,new LinearLayout.LayoutParams(-1,p.dp(44)));
  LinearLayout backing=new LinearLayout(app);backing.setPadding(p.dp(6),p.dp(6),p.dp(6),p.dp(6));backing.setBackground(ToolPage.texture(app));HorizontalScrollView scroll=new HorizontalScrollView(app);scroll.setFillViewport(true);scroll.setBackground(ToolPage.rounded(app,0xffd4e4e3,10));FormulaPreview formula=new FormulaPreview(app,tree,source,false,android.graphics.Color.BLACK,18);formula.setOnClickListener(v->use.run());scroll.addView(formula,new android.widget.FrameLayout.LayoutParams(-1,-2));backing.addView(scroll,new LinearLayout.LayoutParams(-1,-2));p.body.addView(backing);p.divider();
 }
